using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    private static int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeBasketIsChargedNinetyFiveHundredCents() =>
        Assert.Equal(9500, ChargedFor(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverBasketIsChargedNineThousandCents() =>
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldBasketIsChargedEightyFiveHundredCents() =>
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));

    // Bronze customer with a tiny basket is charged a whole cent in their favour
    [Fact]
    public void S4_BronzeSevenCentBasketIsChargedSevenCents() =>
        Assert.Equal(7, ChargedFor(LoyaltyTier.Bronze, 7));
}

